def transform(grid):
    h, w = len(grid), len(grid[0])
    bh, bw = h // 3, w // 3
    blocks = [
        [grid[r][c] for r in range(i * bh, (i + 1) * bh)
                     for c in range(j * bw, (j + 1) * bw)]
        for i in range(3) for j in range(3)
    ]

    # The background color occurs in every block.
    common = set(blocks[0])
    for block in blocks[1:]:
        common &= set(block)
    if common:
        background = max(common, key=lambda color: sum(row.count(color) for row in grid))
    else:
        background = max(set(v for row in grid for v in row),
                         key=lambda color: sum(row.count(color) for row in grid))

    out = []
    for i in range(3):
        row_out = []
        for j in range(3):
            block = blocks[i * 3 + j]
            counts = {}
            for color in block:
                if color != background:
                    counts[color] = counts.get(color, 0) + 1
            row_out.append(max(counts, key=counts.get) if counts else background)
        out.append(row_out)
    return out
