def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each output cell represents a 3x3 input patch; the most frequent
    # overall color is the background, and the patch's signal is its
    # most frequent non-background color.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    out = []
    for r in range(0, h, 3):
        out_row = []
        for c in range(0, w, 3):
            patch_counts = {}
            for row in grid[r:r + 3]:
                for value in row[c:c + 3]:
                    if value != background:
                        patch_counts[value] = patch_counts.get(value, 0) + 1
            out_row.append(max(patch_counts, key=patch_counts.get)
                           if patch_counts else background)
        out.append(out_row)
